def is_balanced(s):
    opens = "([{"
    closes = ")]}"
    stack = []
    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif ch in closes:
            if not stack:
                return False
            stack.pop()
    return not stack

from solution import is_balanced


def test_simple():
    assert is_balanced("()") == True


def test_nested():
    assert is_balanced("([]{})") == True


def test_deep():
    assert is_balanced("((()))") == True


def test_empty():
    assert is_balanced("") == True


def test_unmatched_open():
    assert is_balanced("(((") == False


def test_wrong_order():
    assert is_balanced(")(") == False


def test_type_mismatch():
    assert is_balanced("([)]") == False

